'use strict';
const $=s=>document.querySelector(s), main=$('#main'), C=window.CP_CONTENT, KEY='ciclismo-pro-v1';
const nav=[['inicio','⌂','Inicio'],['bicicletas','♧','Mis bicicletas y equipo'],['taller','⚒','Taller'],['aprender','AIA','Aprender · AIA'],['salidas','↗','Salidas y progreso'],['biblioteca','▤','Biblioteca'],['espacio','◉','Mi espacio']];
// Shared section icons: vector paths inherit the existing app palette.
function sectionIcon(id){
if(id==='bicicletas')return '<img class="section-icon brand-bike" src="assets/section-bike-logo.png" alt="" aria-hidden="true">';
const shapes={
inicio:'<path d="M6 22 24 7l18 15M11 19v22h26V19M20 41V28h8v13"/>',
bicicletas:'<circle cx="11" cy="33" r="8"/><circle cx="37" cy="33" r="8"/><path d="m11 33 9-19 12 19H11l13-14h8M16 14h9M37 33l-8-23h-5"/>',
taller:'<path d="M29 8a11 11 0 0 0-13 14L5 33a6 6 0 0 0 10 10l12-12A11 11 0 0 0 41 17l-8 8-9-9 8-8Z"/><circle cx="11" cy="37" r="1"/>',
salidas:'<circle cx="11" cy="37" r="4"/><circle cx="37" cy="11" r="4"/><path d="M15 37h15a8 8 0 0 0 0-16H18a7 7 0 0 1 0-14h10M26 5l4 2-4 3"/>',
biblioteca:'<path d="M24 12C17 7 10 7 4 10v29c7-3 14-2 20 2 6-4 13-5 20-2V10c-6-3-13-3-20 2v29M10 16c3-1 6 0 9 1M10 23c3-1 6 0 9 1M29 17c3-1 6-2 9-1M29 24c3-1 6-2 9-1"/>',
espacio:'<circle cx="24" cy="15" r="8"/><path d="M8 42v-5a16 16 0 0 1 32 0v5Z"/>',
preparar:'<rect x="10" y="8" width="29" height="35" rx="4"/><path d="M19 8V5h11v7H19V8M17 27l5 5 10-12"/>',
mantenimiento:'<circle cx="24" cy="24" r="18"/><path d="M24 13v12l8 5M20 4h8"/>',
diagnostico:'<circle cx="20" cy="20" r="13"/><path d="m30 30 12 12M20 12v10M20 27h.01"/>'
};
if(id==='aprender')return '<svg class="section-icon aia-wheel" viewBox="0 0 48 48" fill="none" stroke="currentColor" aria-hidden="true" focusable="false"><circle cx="24" cy="24" r="20" stroke-width="4" stroke-dasharray="2 2"/><circle cx="24" cy="24" r="16.5" stroke-width="1.8"/><path d="M24 8v5m0 22v5M10 15l4 3m20 12 4 3M10 33l4-3m20-12 4-3" stroke-width="1.4"/><text x="24" y="29" text-anchor="middle" fill="currentColor" stroke="none" font-family="Aptos,Segoe UI,Arial,sans-serif" font-size="14" font-weight="800" letter-spacing="-.6">AIA</text></svg>';
return '<svg class="section-icon" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+(shapes[id]||shapes.bicicletas)+'</svg>';
}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():'local-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const fresh=name=>({id:uid(),name,bike:'Procaliber',favorites:[],recent:[],checks:{},maintenance:[],rides:[],learning:{},settings:{}});
let state;try{state=JSON.parse(localStorage.getItem(KEY));if(!validState(state))throw 0;}catch{state={version:1,active:'',profiles:[fresh('Mi perfil')]};state.active=state.profiles[0].id;}
function validProfile(p){return p&&typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.favorites)&&Array.isArray(p.recent)&&Array.isArray(p.maintenance)&&Array.isArray(p.rides)&&p.checks&&typeof p.checks==='object'&&p.learning&&typeof p.learning==='object'&&p.settings&&typeof p.settings==='object';}
function validState(s){return s&&s.version===1&&Array.isArray(s.profiles)&&s.profiles.length>0&&s.profiles.length<=30&&s.profiles.every(validProfile)&&s.profiles.some(p=>p.id===s.active);}
const profile=()=>state.profiles.find(p=>p.id===state.active);
let resources=[], quiz=null, step=0, checked=false, correct=0, query='', deferred;
function toast(s){$('#toast').textContent=s;setTimeout(()=>$('#toast').textContent='',4200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('No se ha podido guardar. Exporta una copia y revisa el espacio del navegador.');return false;}}
function profileOptions(){ $('#profile').innerHTML=state.profiles.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('');$('#profile').value=state.active;}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog').showModal();}
function recent(id){let p=profile();p.recent=[id,...p.recent.filter(x=>x!==id)].slice(0,12);save();}
function favorite(id){let p=profile();p.favorites=p.favorites.includes(id)?p.favorites.filter(x=>x!==id):[...p.favorites,id];save();toast(p.favorites.includes(id)?'Guardado en favoritos':'Eliminado de favoritos');}
function fav(id){return `<button data-fav="${esc(id)}" aria-label="Guardar en favoritos">${profile().favorites.includes(id)?'★':'☆'}</button>`;}
function resource(id){return resources.find(r=>r.id===id);}
function sourceLink(id,page){let r=resource(id);return r?`<button data-doc="${id}" ${page?`data-page="${page}"`:''}>Consultar fuente${page?' · p. '+page:''}</button>`:'';}
function doc(id,page){let r=resource(id);if(!r)return;recent('d'+id);let url=r.url+(page&&!r.private?'#page='+page:'');modal(r.title,`<p><span class="tag">${esc(r.type)}</span> ${esc(r.version)}</p><div class="banner small">${esc(r.notes)}</div><div class="row"><a class="primary button-link" href="${esc(r.originalURL||url)}" target="_blank" rel="noopener">${r.private?'Abrir archivo privado':'Abrir original'}</a>${!r.private?`<a href="${esc(r.originalURL||r.url)}" ${r.originalURL?'target="_blank" rel="noopener"':'download'}>Descargar ${r.url.endsWith('pdf')?'PDF':'Word'}</a>`:''}${fav('d'+id)}</div>${r.private?'<p class="muted small">Se abrirá tu archivo privado en ChatGPT. No se ha incluido en los archivos del sitio.</p>':r.url.endsWith('.pdf')?`${r.parts?`<label>Vista por partes<select id="pdf-part">${r.parts.map((v,i)=>`<option value="${v}">Parte ${i+1} de ${r.parts.length} · pliegos ${i*9+1}–${i*9+9}</option>`).join('')}</select></label>`:''}<iframe class="doc-frame" title="Vista previa del documento original" src="${esc(url)}"></iframe><p class="small muted">Si tu dispositivo no muestra el PDF, utiliza Abrir original. Las guías históricas conservan su montaje y versión originales.</p>`:`<details open><summary>Texto de consulta del Word</summary><pre class="document-text">${esc(r.text)}</pre></details>`}`);}
function openProcedure(id){let p=C.procedures.find(p=>p.id===id);if(!p)return;recent('p'+id);modal(p.title,`<div class="row"><span class="tag">${esc(p.level)}</span><span class="tag">${esc(p.bike)}</span>${fav('p'+id)}</div><p style="margin-top:15px"><strong>Herramientas:</strong> ${esc(p.tools)}</p>${p.photo?`<button data-photo="${p.photo}" aria-label="Ampliar foto de cepillos"><img class="brushes" src="assets/${p.photo}" alt="Tus cinco cepillos Muc-Off"></button>`:''}<div class="banner"><strong>Antes de continuar</strong><p>${esc(p.stop)}</p></div>${p.steps.map((s,i)=>`<div class="step"><span class="number">${i+1}</span><div>${esc(s)}</div></div>`).join('')}<details><summary>Errores que evitar</summary><p>${esc(p.avoid)}</p></details><p class="small muted">Ficha adaptada al montaje actual. Consulta también las advertencias del original. Las cifras críticas requieren pieza exacta y fuente.</p>${sourceLink(p.source,p.page)}`);}
function action(symbol,title,sub,href){return `<a class="card action" href="#${href}" style="text-decoration:none;color:inherit"><span class="symbol" aria-hidden="true">${sectionIcon(href==='salidas'?'preparar':href)}</span><span><strong>${title}</strong><small>${sub}</small></span></a>`;}
function heading(k,t,d=''){return `<p class="eyebrow" style="margin:0 0 10px">${k}</p><h1>${t}</h1>${d?`<p class="muted">${d}</p>`:''}`;}
function due(){return profile().maintenance.filter(m=>m.next&&m.next<=new Date().toLocaleDateString('sv-SE'));}
function home(){let p=profile(),done=Object.values(p.learning).filter(x=>x.passed).length;return `<section class="hero"><div><p class="eyebrow">TU BICICLETA. TU RECORRIDO.</p><h1>Más confianza.<br>En cada salida.</h1><p>Conoce tu equipo, cuida lo que te mueve y aprende a disfrutar del camino.</p><button class="primary" data-go="salidas">Preparar mi salida →</button></div><figure class="hero-image"><img src="assets/trek-jose-portada.webp" alt="Mi Trek Procaliber azul y morada"><figcaption>Mi Trek Procaliber · bicicleta personal.</figcaption></figure></section><div class="grid">${action('✓','Preparar salida','Revisión, equipo y seguridad','salidas')}${action('⚒','Resolver un problema','Comprobaciones guiadas','diagnostico')}${action('♧','Consultar mi bicicleta','Componentes y ajustes','bicicletas')}${action('◷','Mantenimiento',p.maintenance.length?`${due().length} avisos según tus fechas`:'Sin historial registrado','mantenimiento')}${action('AIA','Continuar aprendiendo',`${done} de 24 conceptos completados`,'aprender')}${action('▤','Consultar biblioteca','23 documentos relacionados','biblioteca')}</div><div class="card row between"><div><h3>Un pequeño avance, bien aprendido.</h3><p class="muted small">Seguridad, técnica, mecánica y preparación. A tu ritmo.</p></div><button data-go="aprender">Mi recorrido →</button></div><div class="grid two" style="margin-top:20px"><div class="card"><h3>Tu configuración de referencia</h3><p>Procaliber Gen 3 · cámaras · tija rígida.<br>Trek 4900 · 26 pulgadas · cámaras.</p><a href="#bicicletas">Ver mis bicicletas</a></div><div class="card"><h3>Consulta reciente</h3>${recentList(p.recent.slice(0,3))}</div></div>`;}
function recentList(ids){return ids.length?`<ul class="list">${ids.map(id=>{let d=id.startsWith('d')?resource(id.slice(1)):C.procedures.find(x=>x.id===id.slice(1));return d?`<li><button ${id.startsWith('d')?'data-doc':'data-procedure'}="${esc(id.slice(1))}">${esc(d.title)}</button></li>`:'';}).join('')}</ul>`:'<p class="muted small">Tus próximas consultas aparecerán aquí.</p>';}
function bikes(){let p=profile(),b=p.bike||'Procaliber',s=p.settings[b]||{};return heading('MI EQUIPO','Mis bicicletas y ajustes','El montaje personal se conserva separado de las especificaciones históricas.')+`<div class="filters"><select id="bike-select" aria-label="Bicicleta activa"><option ${b==='Procaliber'?'selected':''}>Procaliber</option><option ${b==='Trek 4900'?'selected':''}>Trek 4900</option></select></div><div class="grid two"><div class="card"><span class="tag">${b==='Procaliber'?'Principal · confirmado en proyecto':'Secundaria · estado de uso por registrar'}</span><h2 style="margin-top:14px">${b==='Procaliber'?'Trek Procaliber 9.5 Gen 3':'Trek 4900'}</h2><dl class="specs">${(b==='Procaliber'?[['Cuadro','OCLV Mountain Carbon · IsoBow · talla L'],['Horquilla','Judy Gold Solo Air · TurnKey · 120 mm'],['Transmisión','Deore M6100 · 12 v · 10–51 · plato 32'],['Frenos','Shimano MT200'],['Pedales','Shimano SPD PD-MT520 negros'],['Ruedas','Kovee 29” · 23 mm internos · Sainte-Anne 2,40'],['Montaje','Con cámaras · tija rígida']]:[['Talla','19,5 pulgadas'],['Ruedas','26 pulgadas · llantas con logo Vittoria'],['Cubiertas','Michelin Country Dry 2 · 26 × 2,0'],['Montaje','Con cámaras'],['Estado','Registrar estado actual antes de planificar uso']]).map(([a,v])=>`<dt>${a}</dt><dd>${v}</dd>`).join('')}</dl><div class="row" style="margin-top:15px">${sourceLink(b==='Procaliber'?'02':'17')}</div></div><div class="card"><h2>Mis ajustes medidos</h2><p class="small muted">Solo datos reales. Conserva unidades y fecha; cambia una variable cada vez.</p><form id="settings-form" class="form-grid">${[['front','Presión delantera (bar)'],['rear','Presión trasera (bar)'],['fork','Horquilla (psi)'],['sag','SAG medido (mm)'],['rebound','Rebote y origen del conteo'],['saddle','Altura sillín (mm)']].map(([k,t])=>`<div><label for="s-${k}">${t}</label><input id="s-${k}" name="${k}" value="${esc(s[k]||'')}" maxlength="100"></div>`).join('')}<div class="full"><label for="s-note">Observaciones</label><textarea id="s-note" name="note" maxlength="1500">${esc(s.note||'')}</textarea><button class="primary">Guardar ajustes</button><p class="small muted">${s.updated?'Última actualización: '+esc(s.updated):'Sin ajustes registrados.'}</p></div></form></div></div><div class="banner small"><strong>Datos históricos:</strong> los 130 psi de una ficha no son una medida actual. Los cuatro clics hacia tortuga carecen de origen de conteo registrado. No se aplicarán automáticamente.</div><h2>Dispositivos y herramientas</h2><div class="grid">${[['Polar Vantage M2','Registro y FC óptica; compartir FC requiere modo sensor y receptor compatible.','05'],['iGPSPORT BSC200S','Pantallas en manillar, navegación y sensores; comprobar funciones según firmware.','07'],['Magene S314','Velocidad o cadencia. Un sensor, un modo cada vez.','06'],['Super B TB-FD40','Herramienta de ruta; no sustituye la dinamométrica.','19'],['Ajustes y comodidad','Posición, presiones y control. Las molestias persistentes necesitan valoración.','12'],['Comparar y elegir','Identifica primero el problema; verifica medidas, compatibilidad y coste. e-MTB requiere además motor, batería y servicio.','09']].map(([t,d,id])=>`<div class="card"><h3>${t}</h3><p class="small muted">${d}</p>${sourceLink(id)}</div>`).join('')}</div>`;}
function workshop(){return heading('TALLER','Cuida tu bicicleta','Pasos claros, herramientas adecuadas y una sola comprobación cada vez.')+`<div class="row"><button class="primary" data-go="diagnostico">Resolver un problema</button><button data-go="mantenimiento">Historial y mantenimiento</button><button data-torque>Consultar pares con fuente</button></div><div class="filters"><label>Aplicabilidad<select id="proc-bike"><option>Ambas bicicletas</option><option>Procaliber</option><option>Trek 4900</option></select></label><label>Lugar<select id="proc-place"><option>Todos</option><option>En casa</option><option>En ruta</option></select></label></div><div id="procedure-list" class="grid">${procedureCards(C.procedures)}</div><div class="banner small">En casa: inspección, limpieza y comprobaciones básicas. Taller: daño estructural, hidráulica, internos de suspensión y operaciones fuera de tu experiencia. No reaprietes tornillos indiscriminadamente.</div>`;}
function procedureCards(ps){return ps.map(p=>`<div class="card"><span class="tag">${p.area}</span><h3 style="margin-top:12px">${p.title}</h3><p class="small muted">${p.level} · ${p.bike}</p><button data-procedure="${p.id}">Ver paso a paso →</button> ${fav('p'+p.id)}</div>`).join('')||'<p>No hay fichas con esta combinación.</p>';}
const symptoms={freno:{q:'¿Hay pérdida de frenada, fuga o daño visible?',yes:'No continúes usando la bicicleta. Solicita revisión profesional.',next:'Comprueba el asentamiento de rueda y eje. Después observa si el roce es continuo o puntual; consulta la ficha de frenos.',procedure:'frenos'},cambio:{q:'¿Hubo un golpe o el cambio se aproxima a los radios?',yes:'Deja de pedalear. No ajustes a ciegas: revisa patilla y cambio en taller.',next:'Empieza por suciedad, lubricación, rueda asentada y eslabones. Si tarda en subir o bajar, consulta la guía Deore antes de tocar tensor; no ajustes topes por cualquier ruido.',source:'04'},presion:{q:'¿Hay corte estructural, talón dañado o llanta fisurada?',yes:'No continúes; una cámara nueva no resuelve ese daño.',next:'Tu montaje usa cámaras. Comprueba válvula, busca el objeto causante y sigue el procedimiento de pinchazo.',procedure:'pinchazo'},ruido:{q:'¿Aparece tras un impacto o con holgura evidente?',yes:'Detén el uso y solicita revisión de la zona afectada.',next:'Con la bicicleta parada, intenta localizar si ocurre al girar rueda, dirección o biela. Compara sentado/de pie solo si es seguro. No rocíes lubricante para ocultarlo.',source:'02'},horquilla:{q:'¿Hay fuga anormal, holgura o funcionamiento impredecible?',yes:'Solicita revisión; no abras una suspensión presurizada.',next:'Identifica el ajuste actual. Comprueba abierto/bloqueado, limpieza y SAG. No copies una presión histórica.',procedure:'horquilla'},sensor:{q:'¿Puedes revisar los dispositivos con la bicicleta detenida?',yes:'Comienza despertando el sensor y confirmando su modo.',next:'Detente en lugar seguro antes de manipularlo.',procedure:'sensores'}};
function diagnosis(){return heading('TALLER / DIAGNÓSTICO','¿Qué ocurre?','Una orientación por descarte, empezando por lo sencillo y seguro.')+`<div class="grid">${[['freno','El freno roza'],['cambio','El cambio salta o tarda'],['presion','Pierde presión'],['ruido','Hay un crujido'],['horquilla','La horquilla no va bien'],['sensor','El sensor no conecta']].map(([id,t])=>`<button class="card action" data-symptom="${id}">${t} →</button>`).join('')}</div><div id="diagnostic-result" aria-live="polite"></div>`;}
function maintenance(){let p=profile();return heading('TALLER / REGISTRO','Mantenimiento','Avisos internos calculados solo con las fechas que registres.')+`<div class="banner">${p.maintenance.length?`${due().length} revisión/es con fecha prevista alcanzada. El historial no sustituye una inspección por condición.`:'Sin historial: no se pueden calcular revisiones vencidas, kilómetros ni horas.'}</div><div class="grid two"><div class="card"><h2>Registrar intervención</h2><form id="maintenance-form"><div class="form-grid"><div><label>Fecha<input name="date" type="date" required></label></div><div><label>Bicicleta<select name="bike"><option>Procaliber</option><option>Trek 4900</option></select></label></div><div><label>Kilómetros acumulados · opcional<input name="km" type="number" min="0" step="0.1"></label></div><div><label>Horas acumuladas · opcional<input name="hours" type="number" min="0" step="0.1"></label></div><div class="full"><label>Trabajo realizado<input name="work" required maxlength="250"></label></div><div><label>Lugar<select name="place"><option>En casa</option><option>Taller</option></select></label></div><div><label>Próxima revisión · opcional<input name="next" type="date"></label></div><div class="full"><label>Notas<textarea name="note" maxlength="1500"></textarea></label><button class="primary">Guardar intervención</button></div></div></form></div><div class="card"><h2>Historial</h2>${p.maintenance.length?`<ul class="list">${[...p.maintenance].reverse().map(m=>`<li><strong>${esc(m.work)}</strong><div class="small muted">${esc(m.date)} · ${esc(m.bike)} · ${esc(m.place)}</div><div class="small">${m.km!==''?esc(m.km)+' km · ':''}${m.hours!==''?esc(m.hours)+' h':''}</div>${m.next?`<span class="tag ${m.next<=new Date().toLocaleDateString('sv-SE')?'warning':''}">Próxima: ${esc(m.next)}</span>`:''}<p class="small">${esc(m.note)}</p><button data-delete-maint="${esc(m.id)}">Eliminar registro</button></li>`).join('')}</ul>`:'<p class="muted">Todavía no hay intervenciones.</p>'}</div></div><details><summary>Qué revisar y cuándo</summary><p>Antes de salir: ruedas y ejes, frenos, dirección, cubiertas y transmisión. Después: daños, suciedad, secado y observaciones. Los intervalos de suspensión deben corresponder a la referencia exacta. No conviertas horas a kilómetros sin una equivalencia oficial.</p>${sourceLink('09')}${sourceLink('02')}</details>`;}
function learning(){let p=profile(),done=Object.values(p.learning).filter(x=>x.passed).length;return heading('APRENDER / AIA','Un avance cada vez','24 microlecciones · 96 preguntas · 12 prácticas. Puedes elegir un tema o seguir tu recorrido.')+`<div class="banner row between"><div><strong>${done} / 24 conceptos completados</strong><div class="small">La práctica física se registra por separado; el cuestionario no acredita dominio.</div></div><button class="primary" data-continue>Continuar mi recorrido →</button></div><div class="filters"><label>Área<select id="lesson-area"><option>Todas</option>${[...new Set(C.lessons.map(l=>l.area))].map(a=>`<option>${a}</option>`).join('')}</select></label></div><div class="grid" id="lesson-list">${lessonCards(C.lessons)}</div>`;}
function lessonCards(ls){return ls.map(l=>{let st=profile().learning[l.id]||{};return `<div class="card"><span class="tag">${l.area}</span><h3 style="margin-top:12px">${l.title}</h3><p class="small muted">${l.intro}</p><p class="small">${st.passed?'✓ Concepto comprendido':'Concepto pendiente'}${l.practical?(st.practiced?' · práctica declarada':' · práctica pendiente'):''}</p><button data-lesson="${l.id}">${st.passed?'Repasar':'Aprender'} →</button></div>`;}).join('');}
function openLesson(id){quiz=C.lessons.find(l=>l.id===Number(id));step=0;correct=0;checked=false;modal(quiz.title,`<span class="tag">${quiz.area}</span><p style="margin-top:15px">${quiz.intro}</p><ul>${quiz.checks.map(c=>`<li>${esc(c[0])}.</li>`).join('')}</ul>${quiz.practical?`<div class="banner"><strong>Práctica propuesta</strong><p>${quiz.practice}</p><label class="check"><input type="checkbox" id="practice-mark" ${profile().learning[quiz.id]?.practiced?'checked':''}>He practicado este ejercicio en condiciones seguras</label><p class="small">Autodeclaración. No equivale a valoración de un instructor.</p></div>`:''}<div class="row"><button class="primary" data-start-quiz>Comprobar lo aprendido</button>${sourceLink(quiz.source)}</div>`);}
function quizView(){checked=false;let pair=quiz.checks[step],reverse=(quiz.id+step)%2===0;let options=reverse?[pair[1],pair[0]]:pair;$('#dialog-body').innerHTML=`<p class="small muted">${quiz.area} · Pregunta ${step+1} de 4</p><div class="progress"><span style="width:${step/4*100}%"></span></div><h3>¿Qué criterio aplicarías?</h3>${options.map((t,i)=>`<button class="quiz-option" data-answer="${i===(reverse?1:0)}">${esc(t)}</button>`).join('')}<div id="quiz-feedback" aria-live="polite"></div>`;}
function answer(ok,button){if(checked)return;checked=true;if(ok)correct++;button.classList.add(ok?'correct':'incorrect');document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);$('#quiz-feedback').innerHTML=`<div class="banner" style="margin-top:15px"><strong>${ok?'Bien razonado.':'Conviene revisarlo.'}</strong><p>${esc(quiz.checks[step][0])}. ${esc(quiz.intro)}</p></div><button class="primary" data-next-question>${step===3?'Ver resultado':'Siguiente pregunta'}</button>`;if(!ok){let v=profile().learning[quiz.id]||{};profile().learning[quiz.id]={...v,errors:(v.errors||0)+1};save();}}
function finishQuiz(){let old=profile().learning[quiz.id]||{},passed=correct===4;profile().learning[quiz.id]={...old,passed:old.passed||passed,last:Date.now(),due:Date.now()+(passed?3*86400000:86400000),score:correct};save();$('#dialog-body').innerHTML=`<h3>${correct} de 4 respuestas correctas</h3><p>${passed?'Concepto completado. Volverá a aparecer en los repasos espaciados.':'Repasa los puntos anteriores antes de repetir. El recorrido propondrá otras lecciones y recuperará este concepto más adelante.'}</p><p class="muted small">Comprender una explicación no acredita la ejecución física ni una reparación avanzada.</p><button data-lesson="${quiz.id}">Volver a la explicación</button>`;}
const pre=['Ruedas bien asentadas y ejes seguros','Cubiertas sin daños y presión comprobada','Frenos y dirección comprobados','Transmisión y cadena revisadas','Cámara, bomba, desmontables y herramienta','Agua, comida y recorrido preparados'];const post=['Inspeccionar cortes, impactos y daños','Limpiar si procede y secar','Cuidar cadena y barras de horquilla','Registrar ruido, incidencia y sensaciones'];
function rides(){let p=profile();return heading('SALIDAS Y PROGRESO','Preparar, rodar y revisar','Comprueba el equipo y conserva datos reales de tus salidas.')+`<div class="grid two"><div class="card"><div class="row between"><h2>Antes de salir</h2><button data-reset-checks>Reiniciar listas</button></div>${pre.map((s,i)=>`<label class="check"><input type="checkbox" data-check="pre${i}" ${p.checks['pre'+i]?'checked':''}>${s}</label>`).join('')}<h3 style="margin-top:20px">Después de salir</h3>${post.map((s,i)=>`<label class="check"><input type="checkbox" data-check="post${i}" ${p.checks['post'+i]?'checked':''}>${s}</label>`).join('')}<p class="status-note" style="margin-top:14px">Marcas persistentes por perfil. Reinicia para una nueva salida.</p></div><div class="card"><h2>Explorar un GPX</h2><p class="small muted">Lectura local. No se envía el archivo. Muestra trazado y distancia calculada; no proporciona navegación ni verifica transitabilidad.</p><label>Archivo GPX<input id="gpx" type="file" accept=".gpx,application/gpx+xml"></label><div id="gpx-result" aria-live="polite"></div><details><summary>Planificar con criterio</summary><p>Valora firme, desnivel, técnica, luz, tiempo, agua y escapatorias. El desnivel del archivo puede contener ruido. No se deduce dificultad técnica del trazado ni se consulta meteorología automáticamente.</p>${sourceLink('14')}</details></div></div><div class="grid two"><div class="card"><h2>Registrar una salida</h2><form id="ride-form" class="form-grid"><div><label>Fecha<input type="date" name="date" required></label></div><div><label>Bicicleta<select name="bike"><option>Procaliber</option><option>Trek 4900</option></select></label></div><div class="full"><label>Recorrido de referencia<input name="route" required maxlength="120" placeholder="Nombre del recorrido para comparar"></label></div><div><label>Distancia (km)<input type="number" name="km" required min="0.1" max="10000" step="0.1"></label></div><div><label>Duración en movimiento (min)<input name="minutes" required type="number" min="1" max="50000"></label></div><div><label>Esfuerzo percibido (1–10)<input name="rpe" type="number" min="1" max="10"></label></div><div><label>Desnivel positivo (m) · opcional<input name="elevation" type="number" min="0" step="1"></label></div><div class="full"><label>Condiciones y sensaciones<textarea name="note" maxlength="1500"></textarea></label><button class="primary">Guardar salida</button></div></form></div><div class="card"><h2>Mi diario</h2>${p.rides.length?`<ul class="list">${[...p.rides].reverse().map(r=>`<li><strong>${esc(r.route)}</strong><div class="small muted">${esc(r.date)} · ${esc(r.bike)}</div><p class="small">${esc(r.km)} km · ${esc(r.minutes)} min${r.rpe?' · RPE '+esc(r.rpe):''}</p><p class="small">${esc(r.note)}</p><button data-delete-ride="${esc(r.id)}">Eliminar</button></li>`).join('')}</ul>`:'<p class="muted">Sin salidas registradas.</p>'}${comparison(p.rides)}</div></div>`;}
function comparison(rs){if(rs.length<2)return '<p class="status-note">Registra al menos dos salidas del mismo recorrido y bicicleta para comparar.</p>';let b=rs.at(-1),a=rs.slice(0,-1).reverse().find(r=>r.route.toLowerCase()===b.route.toLowerCase()&&r.bike===b.bike);if(!a)return '<p class="small muted">Todavía no hay dos registros del mismo recorrido y bicicleta.</p>';return `<div class="banner"><strong>${esc(b.route)}</strong><p class="small">Duración: ${esc(a.minutes)} → ${esc(b.minutes)} min. Distancia: ${esc(a.km)} → ${esc(b.km)} km.</p><p class="small">Compara condiciones, paradas y esfuerzo antes de interpretar cambios. No demuestra por sí solo una mejora física.</p></div>`;}
function library(){return heading('BIBLIOTECA','Todo tu material, conectado','Originales, versiones y fichas prácticas. Busca también dentro del texto disponible.')+`<div class="filters"><input id="lib-query" type="search" aria-label="Buscar en biblioteca" placeholder="Cadena, horquilla, limpieza…"><select id="lib-type" aria-label="Tipo"><option value="">Todos los tipos</option><option value="oficial">Manuales oficiales</option><option value="propia">Guías y fichas propias</option><option value="privado">Archivo privado</option></select><select id="lib-bike" aria-label="Bicicleta o equipo"><option value="">Todas las bicicletas y equipo</option><option value="Procaliber">Procaliber</option><option value="4900">Trek 4900</option><option value="S314">Magene S314</option><option value="BSC200S">BSC200S</option><option value="Polar">Polar</option></select></div><p id="lib-count" class="small muted"></p><div class="grid" id="lib-list"></div>`;}
function filterLibrary(){let q=normalize($('#lib-query')?.value||''),t=$('#lib-type')?.value,b=$('#lib-bike')?.value;let rs=resources.filter(r=>normalize([r.title,r.notes,r.section,r.text||''].join(' ')).includes(q)&&(!t||(t==='privado'?r.private:t==='oficial'?r.type.includes('oficial'):!r.private&&!r.type.includes('oficial')))&&(!b||normalize(r.title+' '+r.section+' '+r.notes+' '+(r.text||'')).includes(normalize(b))));$('#lib-count').textContent=rs.length+' de '+resources.length+' recursos';$('#lib-list').innerHTML=rs.map(r=>`<article class="card library-card"><div><span class="tag ${r.private?'warning':''}">${esc(r.type)}</span><h3 style="margin-top:12px">${esc(r.title)}</h3><p class="small muted">${esc(r.version)}${r.pages?' · '+r.pages+' páginas PDF':''}</p><p class="small">${esc(r.notes)}</p></div><div class="row"><button data-doc="${r.id}">${r.private?'Archivo privado ↗':'Consultar →'}</button>${fav('d'+r.id)}</div></article>`).join('')||'<p>No hay documentos con esos filtros.</p>';}
function normalize(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function space(){let p=profile();return heading('MI ESPACIO','Tu recorrido, a tu manera','Perfiles locales y copias de seguridad. No hay sincronización automática entre dispositivos.')+`<div class="grid two"><div class="card"><h2>Perfiles de este navegador</h2><form id="profile-form"><label>Nuevo perfil<input name="name" maxlength="60" required placeholder="Nombre"></label><button class="primary">Crear perfil</button></form><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><form id="rename-form"><label>Nombre del perfil activo<input name="name" maxlength="60" required value="${esc(p.name)}"></label><button>Renombrar</button></form><p class="small muted">Cada perfil separa ajustes, registros y progreso. No es una cuenta con contraseña ni una barrera de seguridad entre personas que usan el mismo navegador.</p></div><div class="card"><h2>Copia y traslado</h2><p>Exporta todos tus perfiles y recupéralos en otro dispositivo. El archivo incluye registros y referencias, sin copiar los manuales.</p><button class="primary" id="export">Exportar mis datos</button><label>Importar copia JSON<input id="import" type="file" accept=".json,application/json"></label><div id="import-preview"></div><p class="small muted">Borrar los datos del navegador o usar navegación privada puede eliminar el progreso. Cada dominio y navegador guarda su propia copia.</p></div></div><div class="grid two"><div class="card"><h2>Favoritos</h2>${recentList(p.favorites)}</div><div class="card"><h2>Consultas recientes</h2>${recentList(p.recent)}</div></div><details><summary>Privacidad, fuentes y alcance de esta versión</summary><p>Esta es la edición pública de la aplicación. Los documentos del proyecto permanecen en la edición privada de ChatGPT Sites. Los registros se guardan en tu navegador. La biblioteca enlaza a la edición privada de Sites, que requiere iniciar sesión. Las guías históricas conservan su texto, que puede describir otro montaje. Las fichas activas toman como referencia cámaras y tija rígida.</p><p>El diagnóstico usa reglas explicables. No consulta tus chats ni se conecta automáticamente a Polar, Strava o iGPSPORT. Los avisos solo aparecen dentro de la aplicación. La instalación depende del navegador; esta versión requiere conexión para los documentos y no promete funcionamiento sin conexión.</p><p>Biblioteca: 20 archivos iniciales y 3 recuperados. Acceso parcial al historial de conversaciones y fotografías; las recreaciones se distinguen de evidencias técnicas. No se ha validado cada ilustración histórica.</p></details>`;}
function searchPage(q){let n=normalize(q),ps=C.procedures.filter(p=>normalize(JSON.stringify(p)).includes(n)),ls=C.lessons.filter(l=>normalize(JSON.stringify(l)).includes(n)),ds=resources.filter(d=>normalize(d.title+' '+d.notes+' '+(d.text||'')).includes(n));return heading('BÚSQUEDA GLOBAL',`Resultados para «${esc(q)}»`)+`<p class="muted">${ps.length} procedimientos · ${ls.length} lecciones · ${ds.length} documentos</p><h2>Fichas prácticas</h2><div class="grid">${procedureCards(ps)}</div><h2>Aprender</h2><div class="grid">${lessonCards(ls)}</div><h2>Documentos</h2><div class="grid">${ds.map(d=>`<div class="card"><h3>${esc(d.title)}</h3><p class="small muted">${esc(d.notes)}</p><button data-doc="${d.id}">Consultar</button></div>`).join('')}</div>`;}
function render(){let route=location.hash.slice(1)||'inicio';$('#nav').innerHTML=nav.map(([id,icon,label])=>`<a href="#${id}" class="${id===route||(id==='taller'&&['diagnostico','mantenimiento'].includes(route))?'active':''}" ${id===route?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${sectionIcon(id)}</span>${label}</a>`).join('');$('#crumb').textContent='Mi espacio / '+(nav.find(n=>n[0]===route)?.[2]||({diagnostico:'Diagnóstico',mantenimiento:'Mantenimiento',buscar:'Búsqueda'}[route]||'Inicio'));let views={inicio:home,bicicletas:bikes,taller:workshop,diagnostico:diagnosis,mantenimiento:maintenance,aprender:learning,salidas:rides,biblioteca:library,espacio:space,buscar:()=>searchPage(query)};main.innerHTML=(views[route]||home)();if(route==='biblioteca')filterLibrary();document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}
let pendingImport;
document.addEventListener('click',e=>{let b=e.target.closest('button,[data-doc],[data-procedure]');if(!b)return;
if(b.dataset.go)location.hash=b.dataset.go;
if(b.dataset.doc){if($('#dialog').open)$('#dialog').close();doc(b.dataset.doc,b.dataset.page);}
if(b.dataset.procedure)openProcedure(b.dataset.procedure);
if(b.dataset.fav){favorite(b.dataset.fav);b.textContent=profile().favorites.includes(b.dataset.fav)?'★':'☆';}
if(b.dataset.photo)modal('Tus cinco cepillos Muc-Off',`<img class="photo-zoom" src="assets/${esc(b.dataset.photo)}" alt="Fotografías de tus cinco cepillos Muc-Off"><p>Fotografías extraídas de la guía de limpieza. Soft Washing, Wheel & Component, Two Prong, Detailing y Claw.</p>`);
if(b.hasAttribute('data-torque'))modal('Pares: identificar antes de apretar','<p>La tabla propia presupone una tija telescópica y no se debe aplicar automáticamente al montaje actual. Consulta el componente y su fijación exacta, estado de la rosca, producto de montaje y rango de la herramienta.</p><p>Un par máximo no se convierte por defecto en objetivo. No uses la multiherramienta como dinamométrica.</p>'+sourceLink('13')+sourceLink('08'));
if(b.dataset.symptom){let s=symptoms[b.dataset.symptom];$('#diagnostic-result').innerHTML=`<div class="card"><h2>${s.q}</h2><div class="row"><button data-diag-choice="yes" data-diag="${b.dataset.symptom}">Sí</button><button data-diag-choice="next" data-diag="${b.dataset.symptom}">No</button></div><div id="diag-detail" aria-live="polite"></div></div>`;}
if(b.dataset.diagChoice){let s=symptoms[b.dataset.diag];$('#diag-detail').innerHTML=`<div class="banner" style="margin-top:15px">${esc(s[b.dataset.diagChoice])}</div>${s.procedure?`<button data-procedure="${s.procedure}">Ver procedimiento</button>`:sourceLink(s.source)}`;}
if(b.dataset.lesson)openLesson(b.dataset.lesson);
if(b.hasAttribute('data-continue')){let ls=C.lessons,now=Date.now(),p=profile();let target=ls.find(l=>!p.learning[l.id])||ls.filter(l=>(p.learning[l.id]?.due||0)<=now).sort((a,b)=>(p.learning[a.id]?.last||0)-(p.learning[b.id]?.last||0))[0]||ls.slice().sort((a,b)=>(p.learning[a.id]?.last||0)-(p.learning[b.id]?.last||0))[0];openLesson(target.id);}
if(b.hasAttribute('data-start-quiz'))quizView();
if(b.dataset.answer!==undefined)answer(b.dataset.answer==='true',b);
if(b.hasAttribute('data-next-question')){step++;if(step<4)quizView();else finishQuiz();}
if(b.hasAttribute('data-reset-checks')){profile().checks={};save();render();toast('Listas listas para una nueva salida');}
if(b.dataset.deleteMaint){profile().maintenance=profile().maintenance.filter(m=>m.id!==b.dataset.deleteMaint);save();render();}
if(b.dataset.deleteRide){profile().rides=profile().rides.filter(m=>m.id!==b.dataset.deleteRide);save();render();}
if(b.id==='export'){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='Ciclismo_PRO_datos_'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
if(b.id==='confirm-import'&&pendingImport){state=pendingImport;pendingImport=null;save();profileOptions();render();toast('Copia importada');}
});
document.addEventListener('submit',e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='profile-form'){if(state.profiles.length>=30)return toast('Máximo 30 perfiles.');let p=fresh(d.name.trim());if(!p.name)return;state.profiles.push(p);state.active=p.id;save();profileOptions();render();toast('Perfil creado');}if(f.id==='rename-form'){if(!d.name.trim())return;profile().name=d.name.trim();save();profileOptions();render();toast('Nombre guardado');}if(f.id==='settings-form'){profile().settings[profile().bike||'Procaliber']={...d,updated:new Date().toLocaleString('es-ES')};save();render();toast('Ajustes guardados');}if(f.id==='maintenance-form'){profile().maintenance.push({...d,id:uid()});save();render();toast('Intervención guardada');}if(f.id==='ride-form'){profile().rides.push({...d,id:uid()});save();render();toast('Salida guardada');}});
document.addEventListener('change',async e=>{let t=e.target;if(t.id==='pdf-part')document.querySelector('.doc-frame').src=t.value;if(t.id==='profile'){state.active=t.value;save();render();}if(t.id==='bike-select'){profile().bike=t.value;save();render();}if(t.dataset.check){profile().checks[t.dataset.check]=t.checked;save();}if(t.id==='practice-mark'&&quiz){let old=profile().learning[quiz.id]||{};profile().learning[quiz.id]={...old,practiced:t.checked};save();}if(t.id==='lesson-area')$('#lesson-list').innerHTML=lessonCards(C.lessons.filter(l=>t.value==='Todas'||l.area===t.value));if(['proc-bike','proc-place'].includes(t.id)){let b=$('#proc-bike').value,p=$('#proc-place').value;$('#procedure-list').innerHTML=procedureCards(C.procedures.filter(x=>(b==='Ambas bicicletas'||x.bike==='Ambas'||x.bike===b)&&(p==='Todos'||x.level.toLowerCase().includes(p.toLowerCase()))));}if(['lib-type','lib-bike'].includes(t.id))filterLibrary();if(t.id==='gpx')await loadGPX(t.files[0]);if(t.id==='import'){try{let f=t.files[0];if(!f)return;if(f.size>5e6)throw Error('Archivo demasiado grande.');let s=JSON.parse(await f.text());if(!validState(s)||!s.profiles.every(p=>p.name.length<=60&&p.id.length<150&&p.favorites.every(x=>typeof x==='string'&&x.length<100)&&p.recent.every(x=>typeof x==='string'&&x.length<100)&&p.maintenance.every(m=>m&&typeof m.id==='string'&&typeof m.work==='string'&&typeof m.date==='string'&&typeof m.bike==='string')&&p.rides.every(r=>r&&typeof r.id==='string'&&typeof r.route==='string'&&Number(r.km)>0&&Number(r.minutes)>0)&&Object.values(p.learning).every(v=>v&&typeof v==='object')))throw Error('Formato o versión no compatible.');pendingImport=s;$('#import-preview').innerHTML=`<div class="banner">${s.profiles.length} perfiles · ${s.profiles.reduce((n,p)=>n+p.maintenance.length,0)} intervenciones · ${s.profiles.reduce((n,p)=>n+p.rides.length,0)} salidas.<p>Se reemplazarán todos los perfiles actuales de este navegador. Exporta antes si deseas conservarlos.</p><button id="confirm-import">Confirmar reemplazo</button></div>`;}catch(err){pendingImport=null;toast('No se ha importado: '+err.message);}}});
document.addEventListener('input',e=>{if(e.target.id==='lib-query')filterLibrary();});
$('#global-search').addEventListener('keydown',e=>{if(e.key==='Enter'){query=e.target.value.trim();if(!query)return;location.hash='buscar';render();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus();}});
$('#close-dialog').onclick=()=>{$('#dialog').close();render();};$('#dialog').addEventListener('cancel',()=>setTimeout(render,0));$('#menu').onclick=()=>{document.body.classList.toggle('menu-open');$('#menu').setAttribute('aria-expanded',String(document.body.classList.contains('menu-open')));};$('#font').onclick=()=>{document.documentElement.classList.toggle('large');};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;$('#install').hidden=false;});$('#install').onclick=async()=>{if(deferred){await deferred.prompt();deferred=null;$('#install').hidden=true;}};
async function loadGPX(file){if(!file)return;const box=$('#gpx-result');try{if(file.size>15e6)throw Error('Usa un GPX de menos de 15 MB.');let xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('XML no válido.');let segments=[...xml.getElementsByTagName('trkseg')].map(s=>[...s.getElementsByTagName('trkpt')]);if(!segments.length)segments=[[...xml.getElementsByTagName('rtept')]];let groups=segments.map(s=>s.map(p=>({lat:Number(p.getAttribute('lat')),lon:Number(p.getAttribute('lon')),ele:p.getElementsByTagName('ele')[0]?.textContent})).filter(p=>Number.isFinite(p.lat)&&Math.abs(p.lat)<=90&&Number.isFinite(p.lon)&&Math.abs(p.lon)<=180));let points=groups.flat();if(points.length<2)throw Error('No hay al menos dos puntos de trazado válidos.');if(points.length>100000)throw Error('El trazado tiene demasiados puntos.');const rad=x=>x*Math.PI/180;let distance=0;for(let g of groups)for(let i=1;i<g.length;i++){let a=g[i-1],b=g[i],v=Math.sin(rad(b.lat-a.lat)/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(rad(b.lon-a.lon)/2)**2;distance+=6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)));}let minLat=Math.min(...points.map(p=>p.lat)),maxLat=Math.max(...points.map(p=>p.lat)),minLon=Math.min(...points.map(p=>p.lon)),maxLon=Math.max(...points.map(p=>p.lon)),cos=Math.cos(rad((minLat+maxLat)/2)),dx=(maxLon-minLon)*cos,dy=maxLat-minLat,scale=Math.min(540/(dx||1e-8),180/(dy||1e-8));let path=groups.map(g=>g.map((p,i)=>`${i?'L':'M'}${(30+(p.lon-minLon)*cos*scale+(540-dx*scale)/2).toFixed(2)},${(200-(p.lat-minLat)*scale-(180-dy*scale)/2).toFixed(2)}`).join(' ')).join(' ');box.innerHTML=`<h3 style="margin-top:18px">${esc(file.name)}</h3><p>${distance.toFixed(2)} km calculados · ${points.length} puntos</p><svg viewBox="0 0 600 220" class="gpx-chart" role="img" aria-label="Esquema del trazado, sin mapa base"><path class="route-line" d="${path}"/></svg><p class="small muted">Esquema de coordenadas sin mapa base. ${points.some(p=>p.ele!==undefined)?'Contiene altitud; no se publica desnivel acumulado sin depurar su ruido.':'Sin altitud: no se puede calcular desnivel.'} No se conectan artificialmente segmentos separados.</p>`;}catch(err){box.innerHTML=`<p role="alert">${esc(err.message)}</p>`;}}
(async()=>{try{resources=await(await fetch('resources.json')).json();profileOptions();save();render();}catch{main.innerHTML='<div class="banner" role="alert">No se ha podido cargar la biblioteca. Recarga con conexión.</div>';}})();
